<template><main class="page"><header><button class="back" @click="$router.back()">← Voltar</button><div class="heading"><div><p class="eyebrow">CENTRO DE ATIVIDADE</p><h1>Notificações</h1></div><button class="reset" @click="clearAll">Limpar notificações</button></div></header><section v-if="items.length" class="list"><article v-for="item in items" :key="item.id" class="item"><span class="dot"></span><div><p>{{ item.message }}</p><small>{{ item.time }}</small></div></article></section><section v-else class="empty"><h2>Tudo em dia</h2><p>As novas notificações recebidas pelo Event Bus aparecerão aqui.</p></section></main></template>
<script setup lang="ts">
import { ref,onMounted,onUnmounted } from 'vue';import {eventBus} from '@core/services/eventBus';
type Notice={id:number;message:string;time:string};const items=ref<Notice[]>([]);let nextId=1;
function receive(payload:any){const message=typeof payload==='string'?payload:payload?.message||payload?.title||'Nova notificação';items.value.unshift({id:nextId++,message:String(message),time:new Date().toLocaleTimeString()});items.value=items.value.slice(0,100);eventBus.emit('ui:notification-badge-update',{count:1});}
function clearAll(){items.value=[];eventBus.emit('ui:notification-badge-reset');}
onMounted(()=>{eventBus.on('notification',receive);eventBus.on('notifications:new',receive);});onUnmounted(()=>{eventBus.off('notification',receive);eventBus.off('notifications:new',receive);});
</script>
<style scoped>.page{max-width:800px;margin:0 auto;padding:24px;color:var(--fg)}header{margin-bottom:20px}.back,.reset{border:1px solid var(--border);background:var(--card-bg);color:var(--fg);border-radius:8px;padding:8px 12px;cursor:pointer}.back{margin-bottom:20px}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.eyebrow{font-size:11px;letter-spacing:.12em;color:var(--muted);margin-bottom:8px}h1{font-size:30px}.list{display:flex;flex-direction:column;gap:8px}.item{display:flex;gap:12px;padding:16px;border:1px solid var(--border);border-radius:10px;background:var(--card-bg)}.dot{width:8px;height:8px;border-radius:50%;background:var(--accent);margin-top:6px;flex-shrink:0}.item p{overflow-wrap:anywhere}.item small{display:block;color:var(--muted);margin-top:6px}.empty{padding:36px 20px;text-align:center;border:1px dashed var(--border);border-radius:12px;color:var(--muted)}.empty h2{color:var(--fg);margin-bottom:8px}</style>